/// Given a non-empty slice of i32, returns an index of a maximum element.
/// If there are multiple maxima, any one of their indices may be returned.
fn find_max(a: &[i32]) -> usize {
    assert!(!a.is_empty(), "Input slice must be non-empty");

    let mut max_idx = 0;
    // Iterate from the second element onward
    for (i, &val) in a.iter().enumerate().skip(1) {
        if val > a[max_idx] {
            max_idx = i;
        }
    }
    max_idx
}

